window.AUTH=window.AUTH||{};window.AUTH["23-1209"]={"d":"23-1209","id":"2025/23-1209","n":"M & K Employee Solutions, LLC v. Trustees of the IAM National Pension Fund","briefs":[{"k":"petitioner","label":"Brief of petitioners M & K Employee Solutions, LLC, et al.","date":"2025-08-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/373166/20250828191339613_2025-08-28%20Brief%20for%20the%20Petitioners.pdf","side":"pet","n":101},{"k":"respondent","label":"Brief of respondents Trustees of the IAM National Pension Fund","date":"2025-10-14","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/379607/20251014182118752_23-1209_Brief%20of%20Respondents.pdf","side":"res","n":20},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-10-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/380210/20251021155127873_23-1209_bsac_MKEmpSols.pdf","side":"us","n":67},{"k":"reply","label":"Reply of petitioners M & K Employee Solutions, LLC, et al.","date":"2025-11-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/384392/20251113135732825_Reply%20Brief%20for%20the%20Petitioners.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us1r34_f2bh.pdf","tr":true,"items":[{"t":"case","label":"Ace-Saginaw Paving Co. v. Operating Eng’rs Loc. 234 Pension Fund, — F.4th —","cite":"2025 WL 2238023","y":2025,"court":"6th Cir.","by":{"0":"29"}},{"t":"case","label":"Aetna Health Inc. v. Davila","cite":"542 U.S. 200","y":2004,"id":"2003/02-1845","sc":1,"sum":"The Court held that Congress intended ERISA to provide a uniform system for regulating retirement schemes and benefits. If a state law conflicts with ERISA, therefore, ERISA must be used in its place.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Atl. Mut. Ins. Co. v. Commissioner","cite":"523 U.S. 382","y":1998,"id":"1997/97-147","sc":1,"sum":"To determine the meaning of \"reserve strengthening\" in the Tax Reform Act of 1986","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"sum":"The Court held that the Commissioner's initial assignments made after October 1, 1993, are valid despite their untimeliness. The Court reasoned that a statute directing official action needed more than a mandatory \"shall\" before the grant of power would be read to expire when the job was supposed to be completed.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17"}},{"t":"case","label":"Boggs v. Boggs","cite":"520 U.S. 833","y":1997,"id":"1996/96-79","sc":1,"sum":"The Court ruled that the Employee Retirement Income Security Act of 1974 (ERISA) preempts state community-property law allowing a non-participant spouse to transfer by a testamentary instrument an interest in undistributed pension plan benefits.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Chi. Truck Drivers, Helpers & Warehouse Workers Union (Indep.) Pension Fund v. CPC Logistics, Inc.","cite":"698 F.3d 346","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/346/","by":{"0":"19, 25, 35"}},{"t":"case","label":"Citrus Valley Ests., Inc. v. Commissioner","cite":"49 F.3d 1410","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/49/1410/","by":{"0":"35"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"sum":"The Court held that, for the purpose of starting the clock on section 2255's one-year limitation period, a judgment of conviction becomes final when the time expires for filing a petition for certiorari contesting the appellate court's affirmation of the conviction. Under this rule, Clay's section 2255 motion was timely filed.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Combs v. Classic Coal Corp.","cite":"931 F.2d 96","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/931/96/","by":{"0":"28"}},{"t":"case","label":"Concrete Pipe & Prods. of Cal., Inc. v. Constr. Laborers Pension Tr. for S. Cal.","cite":"508 U.S. 602","y":1993,"id":"1992/91-904","sc":1,"op":1,"ar":2,"sum":"The Multiemployer Pension Plan Amendments Act of 1980 (MPPAA) amended the Employee Retirement Income Security Act of 1974 (ERISA) to provide that in certain circumstances an employer withdrawing from a multiemployer plan incurs as \"withdrawal liability\" a share of the plan's unfunded vested benefits, 29 U. S. C. §§ 1381, 1391. Withdrawal liability is assessed by means of a notification by the \"plan sponsor\" and a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5-6, 17, 25, 28, 34-36, 40","1":"8, 25, 30-31, 37-38","2":"3, 10, 12, 16, 21, 28, 29, 34","3":"21"}},{"t":"case","label":"Conkright v. Frommert","cite":"559 U.S. 506","y":2010,"id":"2009/08-810","sc":1,"sum":"The Court held that the Second Circuit Court of Appeals erred when they did not hold a claim of unfair pension distribution by employees of the Xerox Corporation to a deferential standard of review.","sumSrc":"Oyez","by":{"0":"24, 44"}},{"t":"case","label":"Connolly v. PBGC","cite":"475 U.S. 211","y":1986,"id":"1985/84-1555","sc":1,"op":1,"sum":"The withdrawal liability provisions of the MPPAA do not violate the Taking Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9","1":"4, 5, 35","2":"3"}},{"t":"case","label":"Fort Halifax Packing Co. v. Coyne","cite":"482 U.S. 1","y":1987,"id":"1986/86-341","sc":1,"sum":"After appellant closed its poultry packaging and processing plant and laid off most of the employees who worked there, the Director of Maine's Bureau of Labor Standards filed suit to enforce the provisions of a state statute requiring employers, in the event of a plant closing, to provide a one-time severance payment to employees not covered by an express contract providing for severance pay. The State Superior …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"589 U.S. 178","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"0":"17","3":"22"}},{"t":"case","label":"Ithaca Tr. Co. v. United States","cite":"279 U.S. 151","y":1929,"id":"scdb/1928-090","sc":1,"sum":"1. Where a will makes bequests to charities, to be paid after the death of the testator's wife from a residuary estate bequeathed to her for life, and allows the wife to use from the principal any sum \"that may be necessary to suitably maintain her in as much comfort as she now enjoys,\" and the income of the estate at the death of the testator, after paying specific debts and legacies, is more than sufficient to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","2":"16, 33","3":"12-13"}},{"t":"case","label":"Joseph Schlitz Brewing Co. v. Milwaukee Brewery Workers’ Pension Plan","cite":"3 F.3d 994","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/3/994/","by":{"0":"30","3":"18"}},{"t":"case","label":"Massachusetts v. Morash","cite":"490 U.S. 107","y":1989,"id":"1988/88-32","sc":1,"sum":"The Court concluded that an employee’s unused vacation time does not constitute an employee welfare benefit plan under the Employment Retirement Income Security Act of 1974.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Metro. Life Ins. Co. v. Massachusetts","cite":"471 U.S. 724","y":1985,"id":"1984/84-325","sc":1,"sum":"A Massachusetts statute (§ 47B) requires that certain minimum mentalhealth-care benefits be provided a Massachusetts resident who is insured under a general health insurance policy or an employee health-care plan that covers hospital and surgical expenses. Appellant insurer in No. 84-325 contends that § 47B, as applied to insurance policies purchased by employee health-care plans regulated by the federal Employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Milwaukee Brewery Workers’ Pension Plan v. Joseph Schlitz Brewing Co.","cite":"513 U.S. 414","y":1995,"id":"1994/93-768","sc":1,"op":3,"sum":"MPPAA calculates its installment schedule on the assumption that interest begins accruing on the first day of the plan year following withdrawal.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 8-10, 14, 16-18, 20-23, 31, 43, 45","1":"1, 5, 7, 20","2":"3, 5, 6, 25, 26, 34","3":"2, 4-5, 10-11, 24"}},{"t":"case","label":"Nachman Corp. v. PBGC","cite":"446 U.S. 359","y":1980,"id":"1979/78-1557","sc":1,"sum":"The plan's limitation of liability clause does not prevent the vested benefits from being characterized as \"nonforfeitable\" and thus covered by the insurance program. Petitioner's argument that the Title I definition of \"nonforfeitable\" determines which benefits are insured under Title IV, that thus benefits are not insured unless they are \"unconditional\" and \"legally enforceable against the plan,\" that because of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Nat’l Ret. Fund v. Metz Culinary Mgmt., Inc.","cite":"946 F.3d 146","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/946/146/","op":1,"sum":"Describing Section 1393 as “silent” about when the assumptions may be selected.","sumSrc":"brief:2","by":{"0":"12-13, 30, 34-35, 37","1":"2-4, 11-16, 20, 28, 34-36","2":"7, 10, 18, 19, 22, 24, 28","3":"15, 21, 23"}},{"t":"case","label":"PBGC v. R.A. Gray & Co.","cite":"467 U.S. 717","y":1984,"id":"1983/83-245","sc":1,"sum":"Application of the withdrawal liability provisions of the MPPAA during the 5-month period prior to the statute's enactment does not violate the Due Process Clause of the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8-9, 17, 23","1":"4-6","2":"4"}},{"t":"case","label":"Rhoades, McKee & Boer v. United States","cite":"43 F.3d 1071","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/43/1071/","by":{"0":"35"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44-45"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"op":2,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31-32","1":"18","2":"19","3":"18"}},{"t":"case","label":"Sofco Erectors, Inc. v. Trs. of Ohio Operating Eng’rs Pension Fund","cite":"15 F.4th 407","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/15/407/","ar":2,"sum":"Rejecting “blended” approach that diluted an actuary’s projection of investment returns with a risk-free rate.","sumSrc":"brief:2","by":{"0":"25, 28, 36, 39","2":"4, 31","3":"6, 24"}},{"t":"case","label":"Till v. SCS Credit Corp.","cite":"541 U.S. 465","y":2004,"id":"2003/02-1016","sc":1,"sum":"Four justices held that the proper rate was the 9.5 percent one arrived at by modifying the average national loan rate to make up for the increased risk of non-payment.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Trs. of IAM Nat’l Pension Fund v. M & K Emp. Sols., LLC","cite":"92 F.4th 316","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/92/316/","op":1,"by":{"0":"4"}},{"t":"case","label":"Trs. of IAM Nat’l Pension Fund v. M & K Emp. Sols., LLC","cite":"2022 WL 4534998","y":2022,"court":"D.D.C. Sept. 28","op":1,"by":{"0":"4"}},{"t":"case","label":"Trs. of IAM Nat’l Pension Fund v. Ohio Magnetics, Inc.","cite":"656 F. Supp. 3d 112","y":2023,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/656/112/","op":1,"by":{"0":"4"}},{"t":"case","label":"United Mine Workers of Am. 1974 Pension Plan v. Energy W. Mining Co.","cite":"39 F.4th 730","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/39/730/","by":{"0":"28, 34, 39","1":"8","2":"30, 31","3":"11"}},{"t":"case","label":"Vinson & Elkins v. Commissioner","cite":"7 F.3d 1235","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/7/1235/","by":{"0":"35"}},{"t":"case","label":"Wachtell, Lipton, Rosen & Katz v. Commissioner","cite":"26 F.3d 291","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/26/291/","by":{"0":"34","1":"16, 31"}},{"t":"usc","label":"26 U.S.C. § 412","url":"https://www.law.cornell.edu/uscode/text/26/412","subs":["(a)(1)","(c)(9)(1976)","(c)(9)(1982)","(c)(3)","(c)(9)"],"stext":{"head":"§412. Minimum funding standards","paras":[[0,"(a) Requirement to meet minimum funding standard"],[0,"(1) In general"],[1,"A plan to which this section applies shall satisfy the minimum funding standard applicable to the plan for any plan year."],[0,"(2) Minimum funding standard"],[1,"For purposes of paragraph (1), a plan shall be treated as satisfying the minimum funding standard for a plan year if—"],[2,"(A) in the case of a defined benefit plan which is not a multiemployer plan or a CSEC plan, the employer makes contributions to or under the plan for the plan year which, in the aggregate, are not less than the minimum required contribution determined under section 430 for the plan for the plan year,"],[2,"(B) in the case of a money purchase plan which is not a multiemployer plan, the employer makes contributions to or under the plan for the plan year which are required under the terms of the plan,"],[2,"(C) in the case of a multiemployer plan, the employers make contributions to or under the plan for any plan year which, in the aggregate, are sufficient to ensure that the plan does not have an accumulated funding deficiency under section 431 as of the end of the plan year, and"],[2,"(D) in the case of a CSEC plan, the employers make contributions to or under the plan for any plan year which, in the aggregate, are sufficient to ensure that the plan does not have an accumulated funding deficiency under section 433 as of the end of the plan year."],[0,"(b) Liability for contributions"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), the amount of any contribution required by this section (including any required installments under paragraphs (3) and (4) of section 430(j) or under section 433(f)) shall be paid by the employer responsible for making contributions to or under the plan."],[0,"(2) Joint and several liability where employer member of controlled group"],[1,"If the employer referred to in paragraph (1) is a member of a controlled group, each member of such group shall be jointly and severally liable for payment of such contributions."],[0,"(3) Multiemployer plans in critical status"],[1,"Paragraph (1) shall not apply in the case of a multiemployer plan for any plan year in which the plan is in critical status pursuant to section 432. This paragraph shall only apply if the plan sponsor adopts a rehabilitation plan in accordance with section 432(e) and complies with such rehabilitation plan (and any modifications of the plan)."],[0,"(c) Variance from minimum funding standards"],[0,"(1) Waiver in case of business hardship"],[0,"(A) In general"],[2,"If—"],[3,"(i) an employer is (or in the case of a multiemployer plan or a CSEC plan, 10 percent or more of the number of employers contributing to or under the plan are) unable to satisfy the minimum funding standard for a plan year without temporary substantial business hardship (substantial business hardship in the case of a multiemployer plan), and"],[3,"(ii) application of the standard would be adverse to the interests of plan participants in the aggregate,"],[2,"the Secretary may, subject to subparagraph (C), waive the requirements of subsection (a) for such year with respect to all or any portion of the minimum funding standard. The Secretary shall not waive the minimum funding standard with respect to a plan for more than 3 of any 15 (5 of any 15 in the case of a multiemployer plan) consecutive plan years."],[0,"(B) Effects of waiver"],[2,"If a waiver is granted under subparagraph (A) for any plan year—"],[3,"(i) in the case of a defined benefit plan which is not a multiemployer plan or a CSEC plan, the minimum required contribution under section 430 for the plan year shall be reduced by the amount of the waived funding deficiency and such amount shall be amortized as required under section 430(e),"],[3,"(ii) in the case of a multiemployer plan, the funding standard account shall be credited under section 431(b)(3)(C) with the amount of the waived funding deficiency and such amount shall be amortized as required under section 431(b)(2)(C), and"],[3,"(iii) in the case of a CSEC plan, the funding standard account shall be credited under section 433(b)(3)(C) with the amount of the waived funding deficiency and such amount shall be amortized as required under section 433(b)(2)(C)."],[0,"(C) Waiver of amortized portion not allowed"],[2,"The Secretary may not waive under subparagraph (A) any portion of the minimum funding standard under subsection (a) for a plan year which is attributable to any waived funding deficiency for any preceding plan year."],[0,"(2) Determination of business hardship"],[1,"For purposes of this subsection, the factors taken into account in determining temporary substantial business hardship (substantial business hardship in the case of a multiemployer plan) shall include (but shall not be limited to) whether or not—"],[2,"(A) the employer is operating at an economic loss,"],[2,"(B) there is substantial unemployment or underemployment in the trade or business and in the industry concerned,"],[2,"(C) the sales and profits of the industry concerned are depressed or declining, and"],[2,"(D) it is reasonable to expect that the plan will be continued only if the waiver is granted."],[0,"(3) Waived funding deficiency"],[1,"For purposes of this section and part III of this subchapter, the term \"waived funding deficiency\" means the portion of the minimum funding standard under subsection (a) (determined without regard to the waiver) for a plan year waived by the Secretary and not satisfied by employer contributions."],[0,"(4) Security for waivers for single-employer plans, consultations"],[0,"(A) Security may be required"],[0,"(i) In general"],[3,"Except as provided in subparagraph (C), the Secretary may require an employer maintaining a defined benefit plan which is a single-employer plan (within the meaning of section 4001(a)(15) of the Employee Retirement Income Security Act of 1974) to provide security to such plan as a condition for granting or modifying a waiver under paragraph (1) or for granting an extension under section 433(d)."],[0,"(ii) Special rules"],[3,"Any security provided under clause (i) may be perfected and enforced only by the Pension Benefit Guaranty Corporation, or at the direction of the Corporation, by a contributing sponsor (within the meaning of section 4001(a)(13) of the Employee Retirement Income Security Act of 1974), or a member of such sponsor's controlled group (within the meaning of section 4001(a)(14) of such Act)."],[0,"(B) Consultation with the Pension Benefit Guaranty Corporation"],[2,"Except as provided in subparagraph (C), the Secretary shall, before granting or modifying a waiver under this subsection or an extension under section 433(d) with respect to a plan described in subparagraph (A)(i)—"],[3,"(i) provide the Pension Benefit Guaranty Corporation with—"],[4,"(I) notice of the completed application for any waiver, modification, or extension, and"],[4,"(II) an opportunity to comment on such application within 30 days after receipt of such notice, and"],[3,"(ii) consider—"],[4,"(I) any comments of the Corporation under clause (i)(II), and"],[4,"(II) any views of any employee organization (within the meaning of section 3(4) of the Employee Retirement Income Security Act of 1974) representing participants in the plan which are submitted in writing to the Secretary in connection with such application."],[2,"Information provided to the Corporation under this subparagraph shall be considered tax return information and subject to the safeguarding and reporting requirements of section 6103(p)."],[0,"(C) Exception for certain waivers or extensions"],[0,"(i) In general"],[3,"The preceding provisions of this paragraph shall not apply to any plan with respect to which the sum of—"],[4,"(I) the aggregate unpaid minimum required contributions (within the meaning of section 4971(c)(4)) for the plan year and all preceding plan years, or the accumulated funding deficiency under section 433, whichever is applicable,"],[4,"(II) the present value of all waiver amortization installments determined for the plan year and succeeding plan years under section 430(e)(2) or 433(b)(2)(C), whichever is applicable, and"],[4,"(III) the total amounts not paid by reason of an extension in effect under section 433(d),"],[0,"is less than $1,000,000."],[0,"(ii) Treatment of waivers or extensions for which applications are pending"],[3,"The amount described in clause (i)(I) shall include any increase in such amount which would result if all applications for waivers or extensions with respect to the minimum funding standard under this subsection which are pending with respect to such plan were denied."],[0,"(5) Special rules for single-employer plans"],[0,"(A) Application must be submitted before date 2½ months after close of year"],[2,"In the case of a defined benefit plan which is not a multiemployer plan, no waiver may be granted under this subsection with respect to any plan for any plan year unless an application therefor is submitted to the Secretary not later than the 15th day of the 3rd month beginning after the close of such plan year."],[0,"(B) Special rule if employer is member of controlled group"],[2,"In the case of a defined benefit plan which is not a multiemployer plan, if an employer is a member of a controlled group, the temporary substantial business hardship requirements of paragraph (1) shall be treated as met only if such requirements are met—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/412?type=usc&year=mostrecent&link-type=html"},"head":"§412. Minimum funding standards","tname":"Internal Revenue Code","by":{"0":"43, 7, 8, 43","3":"10, 10"}},{"t":"usc","label":"26 U.S.C. § 431","url":"https://www.law.cornell.edu/uscode/text/26/431","subs":["(c)(7)(A)"],"by":{"0":"8"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 99-272","url":"https://www.govinfo.gov/link/statute/100/82","by":{"0":"7"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"5","2":"1, 18, 19, 21, 25-28, 33, 34"}},{"t":"usc","label":"29 U.S.C. § 1001a","url":"https://www.law.cornell.edu/uscode/text/29/1001a","subs":["(c)","(c)(2)"],"by":{"0":"13, 44, 44"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(2)","(37)","(37)(A)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1002. Definitions","tname":"Labor","by":{"0":"5, 5, 5, 32"}},{"t":"usc","label":"29 U.S.C. § 1021","url":"https://www.law.cornell.edu/uscode/text/29/1021","subs":["(l)","(l)(1)(A)"],"stext":{"head":"§1021. Duty of disclosure and reporting","paras":[[0,"(a) Summary plan description and information to be furnished to participants and beneficiaries"],[0,"The administrator of each employee benefit plan shall cause to be furnished in accordance with section 1024(b) of this title to each participant covered under the plan and to each beneficiary who is receiving benefits under the plan—"],[1,"(1) a summary plan description described in section 1022(a)(1) 1 of this title; and"],[1,"(2) the information described in subsection (f) and sections 1024(b)(3) and 1025(a) and (c) of this title."],[0,"(b) Reports to be filed with Secretary of Labor"],[0,"The administrator shall, in accordance with section 1024(a) of this title, file with the Secretary—"],[1,"(1) the annual report containing the information required by section 1023 of this title; and"],[1,"(2) terminal and supplementary reports as required by subsection (c) of this section."],[0,"(c) Terminal and supplementary reports"],[0,"(1) Each administrator of an employee pension benefit plan which is winding up its affairs (without regard to the number of participants remaining in the plan) shall, in accordance with regulations prescribed by the Secretary, file such terminal reports as the Secretary may consider necessary. A copy of such report shall also be filed with the Pension Benefit Guaranty Corporation."],[0,"(2) The Secretary may require terminal reports to be filed with regard to any employee welfare benefit plan which is winding up its affairs in accordance with regulations promulgated by the Secretary."],[0,"(3) The Secretary may require that a plan described in paragraph (1) or (2) file a supplementary or terminal report with the annual report in the year such plan is terminated and that a copy of such supplementary or terminal report in the case of a plan described in paragraph (1) be also filed with the Pension Benefit Guaranty Corporation."],[0,"(d) Notice of failure to meet minimum funding standards"],[0,"(1) In general"],[1,"If an employer maintaining a plan other than a multiemployer plan fails to make a required installment or other payment required to meet the minimum funding standard under section 1082 of this title to a plan before the 60th day following the due date for such installment or other payment, the employer shall notify each participant and beneficiary (including an alternate payee as defined in section 1056(d)(3)(K) of this title) of such plan of such failure. Such notice shall be made at such time and in such manner as the Secretary may prescribe."],[0,"(2) Subsection not to apply if waiver pending"],[1,"This subsection shall not apply to any failure if the employer has filed a waiver request under section 1083 or 1085a of this title with respect to the plan year to which the required installment relates, except that if the waiver request is denied, notice under paragraph (1) shall be provided within 60 days after the date of such denial."],[0,"(3) Definitions"],[1,"For purposes of this subsection, the terms \"required installment\" and \"due date\" have the same meanings given such terms by section 1083(j) or 1085a(f) of this title, whichever is applicable."],[0,"(e) Notice of transfer of excess pension assets to health benefits accounts"],[0,"(1) Notice to participants"],[1,"Not later than 60 days before the date of a qualified transfer by an employee pension benefit plan of excess pension assets to a health benefits account or applicable life insurance account, the administrator of the plan shall notify (in such manner as the Secretary may prescribe) each participant and beneficiary under the plan of such transfer. Such notice shall include information with respect to the amount of excess pension assets, the portion to be transferred, the amount of health benefits liabilities or applicable life insurance benefit liabilities expected to be provided with the assets transferred, and the amount of pension benefits of the participant which will be nonforfeitable immediately after the transfer."],[0,"(2) Notice to Secretaries, administrator, and employee organizations"],[0,"(A) In general"],[2,"Not later than 60 days before the date of any qualified transfer by an employee pension benefit plan of excess pension assets to a health benefits account or applicable life insurance account, the employer maintaining the plan from which the transfer is made shall provide the Secretary, the Secretary of the Treasury, the administrator, and each employee organization representing participants in the plan a written notice of such transfer. A copy of any such notice shall be available for inspection in the principal office of the administrator."],[0,"(B) Information relating to transfer"],[2,"Such notice shall identify the plan from which the transfer is made, the amount of the transfer, a detailed accounting of assets projected to be held by the plan immediately before and immediately after the transfer, and the current liabilities under the plan at the time of the transfer."],[0,"(C) Authority for additional reporting requirements"],[2,"The Secretary may prescribe such additional reporting requirements as may be necessary to carry out the purposes of this section."],[0,"(3) Definitions"],[1,"For purposes of paragraph (1), any term used in such paragraph which is also used in section 420 of title 26 (as in effect on December 29, 2022) shall have the same meaning as when used in such section."],[0,"(f) Defined benefit plan funding notices"],[0,"(1) In general"],[1,"The administrator of a defined benefit plan to which subchapter III applies shall for each plan year provide a plan funding notice to the Pension Benefit Guaranty Corporation, to each plan participant and beneficiary, to each labor organization representing such participants or beneficiaries, and, in the case of a multiemployer plan, to each employer that has an obligation to contribute to the plan."],[0,"(2) Information contained in notices"],[0,"(A) Identifying information"],[2,"Each notice required under paragraph (1) shall contain identifying information, including the name of the plan, the address and phone number of the plan administrator and the plan's principal administrative officer, each plan sponsor's employer identification number, and the plan number of the plan."],[0,"(B) Specific information"],[2,"A plan funding notice under paragraph (1) shall include—"],[3,"(i)(I) in the case of a single-employer plan, a statement as to whether the plan's percentage of plan liabilities funded (as described in clause (ii)(I)(bb)) for the plan year to which the notice relates, and for the 2 preceding plan years, is at least 100 percent (and, if not, the actual percentages), or"],[3,"(II) in the case of a multiemployer plan, a statement as to whether the plan's funded percentage (as defined in section 1085(i) 1 of this title) for the plan year to which the notice relates, and for the 2 preceding plan years, is at least 100 percent (and, if not, the actual percentages),"],[3,"(ii)(I) in the case of a single-employer plan—"],[4,"(aa) a statement of the value of the plan's assets and liabilities for the plan year to which the notice relates as of the last day of the plan year to which the notice relates, and for the preceding 2 plan years as of the last day of each such plan year, determined using the asset valuation under subclause (II) of section 1306(a)(3)(E)(iii) of this title and the interest rate under section 1306(a)(3)(E)(iv) of this title,"],[4,"(bb) for purposes of the statement in subparagraph (B)(i)(I), the percentage of plan liabilities funded, calculated as the ratio between the value of the plan's assets and liabilities, as determined under item (aa), for the plan year to which the notice relates and for the 2 preceding plan years, and"],[4,"(cc) if the information in (aa) and (bb) is presented in tabular form, a statement that describes that in the event of a plan termination the corporation's calculation of plan liabilities may be greater and that references the section of the notice with the information required under clause (x), and"],[3,"(II) in the case of a multiemployer plan, a statement, for the plan year to which the notice relates and the preceding 2 plan years, of the value of the plan assets (determined both in the same manner as under section 1084 of this title and under the rules of subclause (I)(aa)) and the value of the plan liabilities (determined in the same manner as under section 1084 of this title except that the method specified in section 1085(i)(8) 1 of this title shall be used),"],[3,"(iii) a statement of the number of participants for the plan year to which the notice relates as of the last day of such plan year and the preceding 2 plan years, in tabular format, who are—"],[4,"(I) retired or separated from service and are receiving benefits,"],[4,"(II) retired or separated participants entitled to future benefits, and"],[4,"(III) active participants under the plan,"],[3,"(iv) a statement setting forth the funding policy of the plan, the asset allocation of investments under the plan (expressed as percentages of total assets), and the average return on assets for the plan year, as of the end of the plan year to which the notice relates,"],[3,"(v) in the case of a multiemployer plan, whether the plan was in critical or endangered status under section 1085 of this title for such plan year and, if so—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1021?type=usc&year=mostrecent&link-type=html"},"head":"§1021. Duty of disclosure and reporting","tname":"Labor","by":{"0":"34, 34","2":"24, 24"}},{"t":"usc","label":"29 U.S.C. § 1023","url":"https://www.law.cornell.edu/uscode/text/29/1023","subs":["(a)(1)(A)","(a)(1)(B)(ii)","(a)(4)(A)","(a)(4)(B)(ii)(1982)","(d)","(d)(1976)","(d)(6)","(d)(6)(1976)","(a)(4)(B)","(a)(4)(B)(ii)"],"stext":{"head":"§1023. Annual reports","paras":[[0,"(a) Publication and filing"],[0,"(1)(A) An annual report shall be published with respect to every employee benefit plan to which this part applies. Such report shall be filed with the Secretary in accordance with section 1024(a) of this title, and shall be made available and furnished to participants in accordance with section 1024(b) of this title."],[0,"(B) The annual report shall include the information described in subsections (b) and (c) and where applicable subsections (d), (e), (f), and (g) and shall also include—"],[1,"(i) a financial statement and opinion, as required by paragraph (3) of this subsection, and"],[1,"(ii) an actuarial statement and opinion, as required by paragraph (4) of this subsection."],[0,"(2) If some or all of the information necessary to enable the administrator to comply with the requirements of this subchapter is maintained by—"],[1,"(A) an insurance carrier or other organization which provides some or all of the benefits under the plan, or holds assets of the plan in a separate account,"],[1,"(B) a bank or similar institution which holds some or all of the assets of the plan in a common or collective trust or a separate trust, or custodial account, or"],[1,"(C) a plan sponsor as defined in section 1002(16)(B) of this title,"],[0,"such carrier, organization, bank, institution, or plan sponsor shall transmit and certify the accuracy of such information to the administrator within 120 days after the end of the plan year (or such other date as may be prescribed under regulations of the Secretary)."],[0,"(3)(A) Except as provided in subparagraph (C), the administrator of an employee benefit plan shall engage, on behalf of all plan participants, an independent qualified public accountant, who shall conduct such an examination of any financial statements of the plan, and of other books and records of the plan, as the accountant may deem necessary to enable the accountant to form an opinion as to whether the financial statements and schedules required to be included in the annual reports by subsection (b) of this section are presented fairly in conformity with generally accepted accounting principles applied on a basis consistent with that of the preceding year. Such examination shall be conducted in accordance with generally accepted auditing standards, and shall involve such tests of the books and records of the plan as are considered necessary by the independent qualified public accountant. The independent qualified public accountant shall also offer his opinion as to whether the separate schedules specified in subsection (b)(3) of this section and the summary material required under section 1024(b)(3) of this title present fairly, and in all material respects the information contained therein when considered in conjunction with the financial statements taken as a whole. The opinion by the independent qualified public accountant shall be made a part of the annual report. In a case where a plan is not required to file an annual report, the requirements of this paragraph shall not apply. In a case where by reason of section 1024(a)(2) of this title a plan is required only to file a simplified annual report, the Secretary may waive the requirements of this paragraph."],[0,"(B) In offering his opinion under this section the accountant may rely on the correctness of any actuarial matter certified to by an enrolled actuary, if he so states his reliance."],[0,"(C) The opinion required by subparagraph (A) need not be expressed as to any statements required by subsection (b)(3)(G) prepared by a bank or similar institution or insurance carrier regulated and supervised and subject to periodic examination by a State or Federal agency if such statements are certified by the bank, similar institution, or insurance carrier as accurate and are made a part of the annual report."],[0,"(D) For purposes of this subchapter, the term \"qualified public accountant\" means—"],[1,"(i) a person who is a certified public accountant, certified by a regulatory authority of a State;"],[1,"(ii) a person who is a licensed public accountant licensed by a regulatory authority of a State; or"],[1,"(iii) a person certified by the Secretary as a qualified public accountant in accordance with regulations published by him for a person who practices in States where there is no certification or licensing procedure for accountants."],[0,"(4)(A) The administrator of an employee pension benefit plan subject to the reporting requirement of subsection (d) of this section shall engage, on behalf of all plan participants, an enrolled actuary who shall be responsible for the preparation of the materials comprising the actuarial statement required under subsection (d) of this section. In a case where a plan is not required to file an annual report, the requirement of this paragraph shall not apply, and, in a case where by reason of section 1024(a)(2) of this title, a plan is required only to file a simplified report, the Secretary may waive the requirement of this paragraph."],[0,"(B) The enrolled actuary shall utilize such assumptions and techniques as are necessary to enable him to form an opinion as to whether the contents of the matters reported under subsection (d) of this section—"],[1,"(i) are in the aggregate reasonably related to the experience of the plan and to reasonable expectations; and"],[1,"(ii) represent his best estimate of anticipated experience under the plan."],[0,"The opinion by the enrolled actuary shall be made with respect to, and shall be made a part of, each annual report."],[0,"(C) For purposes of this subchapter, the term \"enrolled actuary\" means an actuary enrolled under subtitle C of subchapter II of this chapter."],[0,"(D) In making a certification under this section the enrolled actuary may rely on the correctness of any accounting matter under subsection (b) to which any qualified public accountant has expressed an opinion, if he so states his reliance."],[0,"(b) Financial statement"],[0,"An annual report under this section shall include a financial statement containing the following information:"],[0,"(1) With respect to an employee welfare benefit plan: a statement of assets and liabilities; a statement of changes in fund balance; and a statement of changes in financial position. In the notes to financial statements, disclosures concerning the following items shall be considered by the accountant: a description of the plan including any significant changes in the plan made during the period and the impact of such changes on benefits; a description of material lease commitments, other commitments, and contingent liabilities; a description of agreements and transactions with persons known to be parties in interest; a general description of priorities upon termination of the plan; information concerning whether or not a tax ruling or determination letter has been obtained; and any other matters necessary to fully and fairly present the financial statements of the plan."],[0,"(2) With respect to an employee pension benefit plan: a statement of assets and liabilities, and a statement of changes in net assets available for plan benefits which shall include details of revenues and expenses and other changes aggregated by general source and application. In the notes to financial statements, disclosures concerning the following items shall be considered by the accountant: a description of the plan including any significant changes in the plan made during the period and the impact of such changes on benefits; the funding policy (including policy with respect to prior service cost), and any changes in such policies during the year; a description of any significant changes in plan benefits made during the period; a description of material lease commitments, other commitments, and contingent liabilities; a description of agreements and transactions with persons known to be parties in interest; a general description of priorities upon termination of the plan; information concerning whether or not a tax ruling or determination letter has been obtained; and any other matters necessary to fully and fairly present the financial statements of such pension plan."],[0,"(3) With respect to all employee benefit plans, the statement required under paragraph (1) or (2) shall have attached the following information in separate schedules:"],[1,"(A) a statement of the assets and liabilities of the plan aggregated by categories and valued at their current value, and the same data displayed in comparative form for the end of the previous fiscal year of the plan;"],[1,"(B) a statement of receipts and disbursements during the preceding twelve-month period aggregated by general sources and applications;"],[1,"(C) a schedule of all assets held for investment purposes aggregated and identified by issuer, borrower, or lessor, or similar party to the transaction (including a notation as to whether such party is known to be a party in interest), maturity date, rate of interest, collateral, par or maturity value, cost, and current value;"],[1,"(D) a schedule of each transaction involving a person known to be party in interest, the identity of such party in interest and his relationship or that of any other party in interest to the plan, a description of each asset to which the transaction relates; the purchase or selling price in case of a sale or purchase, the rental in case of a lease, or the interest rate and maturity date in case of a loan; expense incurred in connection with the transaction; the cost of the asset, the current value of the asset, and the net gain (or loss) on each transaction;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1023?type=usc&year=mostrecent&link-type=html"},"head":"§1023. Annual reports","tname":"Labor","by":{"0":"33, 6, 6, 6, 26, 6, 7, 7, 6","2":"25, 27","3":"9, 9, 9, 9"}},{"t":"usc","label":"29 U.S.C. § 1024","url":"https://www.law.cornell.edu/uscode/text/29/1024","subs":["(a)(1)"],"stext":{"head":"§1024. Filing with Secretary and furnishing information to participants and certain employers","paras":[[0,"(a) Filing of annual report with Secretary"],[0,"(1) The administrator of any employee benefit plan subject to this part shall file with the Secretary the annual report for a plan year within 210 days after the close of such year (or within such time as may be required by regulations promulgated by the Secretary in order to reduce duplicative filing). The Secretary shall make copies of such annual reports available for inspection in the public document room of the Department of Labor."],[0,"(2)(A) With respect to annual reports required to be filed with the Secretary under this part, the Secretary may by regulation prescribe simplified annual reports for any pension plan that—"],[1,"(i) covers fewer than 100 participants; or"],[1,"(ii) is a plan described in section 1060(a) of this title that covers fewer than 1,000 participants, but only if no single employer in the plan has 100 or more participants covered by the plan."],[0,"(B) Nothing contained in this paragraph shall preclude the Secretary from requiring any information or data from any such plan to which this part applies where he finds such data or information is necessary to carry out the purposes of this subchapter nor shall the Secretary be precluded from revoking provisions for simplified reports for any such plan if he finds it necessary to do so in order to carry out the objectives of this subchapter."],[0,"(3) The Secretary may by regulation exempt any welfare benefit plan from all or part of the reporting and disclosure requirements of this subchapter, or may provide for simplified reporting and disclosure if he finds that such requirements are inappropriate as applied to welfare benefit plans."],[0,"(4) The Secretary may reject any filing under this section—"],[1,"(A) if he determines that such filing is incomplete for purposes of this part; or"],[1,"(B) if he determines that there is any material qualification by an accountant or actuary contained in an opinion submitted pursuant to section 1023(a)(3)(A) or section 1023(a)(4)(B) of this title."],[0,"(5) If the Secretary rejects a filing of a report under paragraph (4) and if a revised filing satisfactory to the Secretary is not submitted within 45 days after the Secretary makes his determination under paragraph (4) to reject the filing, and if the Secretary deems it in the best interest of the participants, he may take any one or more of the following actions—"],[1,"(A) retain an independent qualified public accountant (as defined in section 1023(a)(3)(D) of this title) on behalf of the participants to perform an audit,"],[1,"(B) retain an enrolled actuary (as defined in section 1023(a)(4)(C) of this title) on behalf of the plan participants, to prepare an actuarial statement,"],[1,"(C) bring a civil action for such legal or equitable relief as may be appropriate to enforce the provisions of this part, or"],[1,"(D) take any other action authorized by this subchapter."],[0,"The administrator shall permit such accountant or actuary to inspect whatever books and records of the plan are necessary for such audit. The plan shall be liable to the Secretary for the expenses for such audit or report, and the Secretary may bring an action against the plan in any court of competent jurisdiction to recover such expenses."],[0,"(6) The administrator of any employee benefit plan subject to this part shall furnish to the Secretary, upon request, any documents relating to the employee benefit plan, including but not limited to, the latest summary plan description (including any summaries of plan changes not contained in the summary plan description), and the bargaining agreement, trust agreement, contract, or other instrument under which the plan is established or operated."],[0,"(b) Publication of summary plan description and annual report to participants and beneficiaries of plan"],[0,"Publication of the summary plan descriptions and annual reports shall be made to participants and beneficiaries of the particular plan as follows:"],[0,"(1) The administrator shall furnish to each participant, and each beneficiary receiving benefits under the plan, a copy of the summary plan description, and all modifications and changes referred to in section 1022(a) of this title—"],[1,"(A) within 90 days after he becomes a participant, or (in the case of a beneficiary) within 90 days after he first receives benefits, or"],[1,"(B) if later, within 120 days after the plan becomes subject to this part."],[0,"The administrator shall furnish to each participant, and each beneficiary receiving benefits under the plan, every fifth year after the plan becomes subject to this part an updated summary plan description described in section 1022 of this title which integrates all plan amendments made within such five-year period, except that in a case where no amendments have been made to a plan during such five-year period this sentence shall not apply. Notwithstanding the foregoing, the administrator shall furnish to each participant, and to each beneficiary receiving benefits under the plan, the summary plan description described in section 1022 of this title every tenth year after the plan becomes subject to this part. If there is a modification or change described in section 1022(a) of this title (other than a material reduction in covered services or benefits provided in the case of a group health plan (as defined in section 1191b(a)(1) of this title)), a summary description of such modification or change shall be furnished not later than 210 days after the end of the plan year in which the change is adopted to each participant, and to each beneficiary who is receiving benefits under the plan. If there is a modification or change described in section 1022(a) of this title that is a material reduction in covered services or benefits provided under a group health plan (as defined in section 1191b(a)(1) of this title), a summary description of such modification or change shall be furnished to participants and beneficiaries not later than 60 days after the date of the adoption of the modification or change. In the alternative, the plan sponsors may provide such description at regular intervals of not more than 90 days. The Secretary shall issue regulations within 180 days after August 21, 1996, providing alternative mechanisms to delivery by mail through which group health plans (as so defined) may notify participants and beneficiaries of material reductions in covered services or benefits."],[0,"(2) The administrator shall make copies of the latest updated summary plan description and the latest annual report and the bargaining agreement, trust agreement, contract, or other instruments under which the plan was established or is operated available for examination by any plan participant or beneficiary in the principal office of the administrator and in such other places as may be necessary to make available all pertinent information to all participants (including such places as the Secretary may prescribe by regulations)."],[0,"(3) Within 210 days after the close of the fiscal year of the plan, the administrator (other than an administrator of a defined benefit plan to which the requirements of section 1021(f) of this title applies) 1 shall furnish to each participant, and to each beneficiary receiving benefits under the plan, a copy of the statements and schedules, for such fiscal year, described in subparagraphs (A) and (B) of section 1023(b)(3) of this title and such other material (including the percentage determined under section 1023(d)(11) of this title) as is necessary to fairly summarize the latest annual report."],[0,"(4) The administrator shall, upon written request of any participant or beneficiary, furnish a copy of the latest updated summary,2 plan description, and the latest annual report, any terminal report, the bargaining agreement, trust agreement, contract, or other instruments under which the plan is established or operated. The administrator may make a reasonable charge to cover the cost of furnishing such complete copies. The Secretary may by regulation prescribe the maximum amount which will constitute a reasonable charge under the preceding sentence."],[0,"(5) Identification and basic plan information and actuarial information included in the annual report for any plan year shall be filed with the Secretary in an electronic format which accommodates display on the Internet, in accordance with regulations which shall be prescribed by the Secretary. The Secretary shall provide for display of such information included in the annual report, within 90 days after the date of the filing of the annual report, on an Internet website maintained by the Secretary and other appropriate media. Such information shall also be displayed on any Intranet website maintained by the plan sponsor (or by the plan administrator on behalf of the plan sponsor) for the purpose of communicating with employees and not the public, in accordance with regulations which shall be prescribed by the Secretary."],[0,"(c) Statement of rights"],[0,"The Secretary may by regulation require that the administrator of any employee benefit plan furnish to each participant and to each beneficiary receiving benefits under the plan a statement of the rights of participants and beneficiaries under this subchapter."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1024?type=usc&year=mostrecent&link-type=html"},"head":"§1024. Filing with Secretary and furnishing information to participants and certain employers","tname":"Labor","by":{"0":"6, 33","2":"25"}},{"t":"usc","label":"29 U.S.C. § 1082","url":"https://www.law.cornell.edu/uscode/text/29/1082","subs":["(a)(1)","(c)(3)(1982)","(c)(9)(1976)","(c)(9)(1994)"],"stext":{"head":"§1082. Minimum funding standards","paras":[[0,"(a) Requirement to meet minimum funding standard"],[0,"(1) In general"],[1,"A plan to which this part applies shall satisfy the minimum funding standard applicable to the plan for any plan year."],[0,"(2) Minimum funding standard"],[1,"For purposes of paragraph (1), a plan shall be treated as satisfying the minimum funding standard for a plan year if—"],[2,"(A) in the case of a defined benefit plan which is a single-employer plan (other than a CSEC plan), the employer makes contributions to or under the plan for the plan year which, in the aggregate, are not less than the minimum required contribution determined under section 1083 of this title for the plan for the plan year,"],[2,"(B) in the case of a money purchase plan which is a single-employer plan, the employer makes contributions to or under the plan for the plan year which are required under the terms of the plan,"],[2,"(C) in the case of a multiemployer plan, the employers make contributions to or under the plan for any plan year which, in the aggregate, are sufficient to ensure that the plan does not have an accumulated funding deficiency under section 1084 of this title as of the end of the plan year, and"],[2,"(D) in the case of a CSEC plan, the employers make contributions to or under the plan for any plan year which, in the aggregate, are sufficient to ensure that the plan does not have an accumulated funding deficiency under section 1085a of this title as of the end of the plan year."],[0,"(b) Liability for contributions"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), the amount of any contribution required by this section (including any required installments under paragraphs (3) and (4) of section 1083(j) of this title or under section 1085a(f) of this title) shall be paid by the employer responsible for making contributions to or under the plan."],[0,"(2) Joint and several liability where employer member of controlled group"],[1,"If the employer referred to in paragraph (1) is a member of a controlled group, each member of such group shall be jointly and severally liable for payment of such contributions."],[0,"(3) Multiemployer plans in critical status"],[1,"Paragraph (1) shall not apply in the case of a multiemployer plan for any plan year in which the plan is in critical status pursuant to section 1085 of this title. This paragraph shall only apply if the plan sponsor adopts a rehabilitation plan in accordance with section 1085(e) of this title and complies with the terms of such rehabilitation plan (and any updates or modifications of the plan)."],[0,"(c) Variance from minimum funding standards"],[0,"(1) Waiver in case of business hardship"],[0,"(A) In general"],[2,"If—"],[3,"(i) an employer is (or in the case of a multiemployer plan or a CSEC plan, 10 percent or more of the number of employers contributing to or under the plan are) unable to satisfy the minimum funding standard for a plan year without temporary substantial business hardship (substantial business hardship in the case of a multiemployer plan), and"],[3,"(ii) application of the standard would be adverse to the interests of plan participants in the aggregate,"],[2,"the Secretary of the Treasury may, subject to subparagraph (C), waive the requirements of subsection (a) for such year with respect to all or any portion of the minimum funding standard. The Secretary of the Treasury shall not waive the minimum funding standard with respect to a plan for more than 3 of any 15 (5 of any 15 in the case of a multiemployer plan) consecutive plan years."],[0,"(B) Effects of waiver"],[2,"If a waiver is granted under subparagraph (A) for any plan year—"],[3,"(i) in the case of a single-employer plan (other than a CSEC plan), the minimum required contribution under section 1083 of this title for the plan year shall be reduced by the amount of the waived funding deficiency and such amount shall be amortized as required under section 1083(e) of this title,"],[3,"(ii) in the case of a multiemployer plan, the funding standard account shall be credited under section 1084(b)(3)(C) of this title with the amount of the waived funding deficiency and such amount shall be amortized as required under section 1084(b)(2)(C) of this title, and"],[3,"(iii) in the case of a CSEC plan, the funding standard account shall be credited under section 1085a(b)(3)(C) of this title with the amount of the waived funding deficiency and such amount shall be amortized as required under section 1085a(b)(2)(C) of this title."],[0,"(C) Waiver of amortized portion not allowed"],[2,"The Secretary of the Treasury may not waive under subparagraph (A) any portion of the minimum funding standard under subsection (a) for a plan year which is attributable to any waived funding deficiency for any preceding plan year."],[0,"(2) Determination of business hardship"],[1,"For purposes of this subsection, the factors taken into account in determining temporary substantial business hardship (substantial business hardship in the case of a multiemployer plan) shall include (but shall not be limited to) whether or not—"],[2,"(A) the employer is operating at an economic loss,"],[2,"(B) there is substantial unemployment or underemployment in the trade or business and in the industry concerned,"],[2,"(C) the sales and profits of the industry concerned are depressed or declining, and"],[2,"(D) it is reasonable to expect that the plan will be continued only if the waiver is granted."],[0,"(3) Waived funding deficiency"],[1,"For purposes of this part, the term \"waived funding deficiency\" means the portion of the minimum funding standard under subsection (a) (determined without regard to the waiver) for a plan year waived by the Secretary of the Treasury and not satisfied by employer contributions."],[0,"(4) Security for waivers for single-employer plans, consultations"],[0,"(A) Security may be required"],[0,"(i) In general"],[3,"Except as provided in subparagraph (C), the Secretary of the Treasury may require an employer maintaining a defined benefit plan which is a single-employer plan (within the meaning of section 1301(a)(15) of this title) to provide security to such plan as a condition for granting or modifying a waiver under paragraph (1) or for granting an extension under section 1085a(d) of this title."],[0,"(ii) Special rules"],[3,"Any security provided under clause (i) may be perfected and enforced only by the Pension Benefit Guaranty Corporation, or at the direction of the Corporation, by a contributing sponsor (within the meaning of section 1301(a)(13) of this title), or a member of such sponsor's controlled group (within the meaning of section 1301(a)(14) of this title)."],[0,"(B) Consultation with the Pension Benefit Guaranty Corporation"],[2,"Except as provided in subparagraph (C), the Secretary of the Treasury shall, before granting or modifying a waiver under this subsection or an extension under 1085a(d) 1 of this title with respect to a plan described in subparagraph (A)(i)—"],[3,"(i) provide the Pension Benefit Guaranty Corporation with—"],[4,"(I) notice of the completed application for any waiver, modification, or extension, and"],[4,"(II) an opportunity to comment on such application within 30 days after receipt of such notice, and"],[3,"(ii) consider—"],[4,"(I) any comments of the Corporation under clause (i)(II), and"],[4,"(II) any views of any employee organization (within the meaning of section 1002(4) of this title) representing participants in the plan which are submitted in writing to the Secretary of the Treasury in connection with such application."],[2,"Information provided to the Corporation under this subparagraph shall be considered tax return information and subject to the safeguarding and reporting requirements of section 6103(p) of title 26."],[0,"(C) Exception for certain waivers or extensions"],[0,"(i) In general"],[3,"The preceding provisions of this paragraph shall not apply to any plan with respect to which the sum of—"],[4,"(I) the aggregate unpaid minimum required contributions for the plan year and all preceding plan years, or the accumulated funding deficiency under section 1085a of this title, whichever is applicable,"],[4,"(II) the present value of all waiver amortization installments determined for the plan year and succeeding plan years under section 1083(e)(2) or 1085a(b)(2)(C) of this title, whichever is applicable, and"],[4,"(III) the total amounts not paid by reason of an extension in effect under section 1085a(d) of this title,"],[0,"is less than $1,000,000."],[0,"(ii) Treatment of waivers or extensions for which applications are pending"],[3,"The amount described in clause (i)(I) shall include any increase in such amount which would result if all applications for waivers or extensions with respect to the minimum funding standard under this subsection which are pending with respect to such plan were denied."],[0,"(iii) Unpaid minimum required contribution"],[3,"For purposes of this subparagraph—"],[0,"(I) In general"],[4,"The term \"unpaid minimum required contribution\" means, with respect to any plan year, any minimum required contribution under section 1083 of this title for the plan year which is not paid on or before the due date (as determined under section 1083(j)(1) of this title) for the plan year."],[0,"(II) Ordering rule"],[4,"For purposes of subclause (I), any payment to or under a plan for any plan year shall be allocated first to unpaid minimum required contributions for all preceding plan years on a first-in, first-out basis and then to the minimum required contribution under section 1083 of this title for the plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1082?type=usc&year=mostrecent&link-type=html"},"head":"§1082. Minimum funding standards","tname":"Labor","by":{"0":"7, 26, 8","2":"6, 25, 26"}},{"t":"usc","label":"29 U.S.C. § 1084","url":"https://www.law.cornell.edu/uscode/text/29/1084","subs":["(c)(7)(A)","(c)(3)","(c)(7)","(c)(7)(B)(i)"],"stext":{"head":"§1084. Minimum funding standards for multiemployer plans","paras":[[0,"(a) In general"],[0,"For purposes of section 1082 of this title, the accumulated funding deficiency of a multiemployer plan for any plan year is the amount, determined as of the end of the plan year, equal to the excess (if any) of the total charges to the funding standard account of the plan for all plan years (beginning with the first plan year for which this part applies to the plan) over the total credits to such account for such years."],[0,"(b) Funding standard account"],[0,"(1) Account required"],[1,"Each multiemployer plan to which this part applies shall establish and maintain a funding standard account. Such account shall be credited and charged solely as provided in this section."],[0,"(2) Charges to account"],[1,"For a plan year, the funding standard account shall be charged with the sum of—"],[2,"(A) the normal cost of the plan for the plan year,"],[2,"(B) the amounts necessary to amortize in equal annual installments (until fully amortized)—"],[3,"(i) in the case of a plan which comes into existence on or after January 1, 2008, the unfunded past service liability under the plan on the first day of the first plan year to which this section applies, over a period of 15 plan years,"],[3,"(ii) separately, with respect to each plan year, the net increase (if any) in unfunded past service liability under the plan arising from plan amendments adopted in such year, over a period of 15 plan years,"],[3,"(iii) separately, with respect to each plan year, the net experience loss (if any) under the plan, over a period of 15 plan years, and"],[3,"(iv) separately, with respect to each plan year, the net loss (if any) resulting from changes in actuarial assumptions used under the plan, over a period of 15 plan years,"],[2,"(C) the amount necessary to amortize each waived funding deficiency (within the meaning of section 1082(c)(3) of this title) for each prior plan year in equal annual installments (until fully amortized) over a period of 15 plan years,"],[2,"(D) the amount necessary to amortize in equal annual installments (until fully amortized) over a period of 5 plan years any amount credited to the funding standard account under section 1082(b)(3)(D) of this title (as in effect on the day before August 17, 2006), and"],[2,"(E) the amount necessary to amortize in equal annual installments (until fully amortized) over a period of 20 years the contributions which would be required to be made under the plan but for the provisions of section 1082(c)(7)(A)(i)(I) of this title (as in effect on the day before August 17, 2006)."],[0,"(3) Credits to account"],[1,"For a plan year, the funding standard account shall be credited with the sum of—"],[2,"(A) the amount considered contributed by the employer to or under the plan for the plan year,"],[2,"(B) the amount necessary to amortize in equal annual installments (until fully amortized)—"],[3,"(i) separately, with respect to each plan year, the net decrease (if any) in unfunded past service liability under the plan arising from plan amendments adopted in such year, over a period of 15 plan years,"],[3,"(ii) separately, with respect to each plan year, the net experience gain (if any) under the plan, over a period of 15 plan years, and"],[3,"(iii) separately, with respect to each plan year, the net gain (if any) resulting from changes in actuarial assumptions used under the plan, over a period of 15 plan years,"],[2,"(C) the amount of the waived funding deficiency (within the meaning of section 1082(c)(3) of this title) for the plan year, and"],[2,"(D) in the case of a plan year for which the accumulated funding deficiency is determined under the funding standard account if such plan year follows a plan year for which such deficiency was determined under the alternative minimum funding standard under section 1085 of this title (as in effect on the day before August 17, 2006), the excess (if any) of any debit balance in the funding standard account (determined without regard to this subparagraph) over any debit balance in the alternative minimum funding standard account."],[0,"(4) Special rule for amounts first amortized in plan years before 2008"],[1,"In the case of any amount amortized under section 1082(b) of this title (as in effect on the day before August 17, 2006) over any period beginning with a plan year beginning before 2008, in lieu of the amortization described in paragraphs (2)(B) and (3)(B), such amount shall continue to be amortized under such section as so in effect."],[0,"(5) Combining and offsetting amounts to be amortized"],[1,"Under regulations prescribed by the Secretary of the Treasury, amounts required to be amortized under paragraph (2) or paragraph (3), as the case may be—"],[2,"(A) may be combined into one amount under such paragraph to be amortized over a period determined on the basis of the remaining amortization period for all items entering into such combined amount, and"],[2,"(B) may be offset against amounts required to be amortized under the other such paragraph, with the resulting amount to be amortized over a period determined on the basis of the remaining amortization periods for all items entering into whichever of the two amounts being offset is the greater."],[0,"(6) Interest"],[1,"The funding standard account (and items therein) shall be charged or credited (as determined under regulations prescribed by the Secretary of the Treasury) with interest at the appropriate rate consistent with the rate or rates of interest used under the plan to determine costs."],[0,"(7) Special rules relating to charges and credits to funding standard account"],[1,"For purposes of this part—"],[0,"(A) Withdrawal liability"],[2,"Any amount received by a multiemployer plan in payment of all or part of an employer's withdrawal liability under part 1 of subtitle E of subchapter III shall be considered an amount contributed by the employer to or under the plan. The Secretary of the Treasury may prescribe by regulation additional charges and credits to a multiemployer plan's funding standard account to the extent necessary to prevent withdrawal liability payments from being unduly reflected as advance funding for plan liabilities."],[0,"(B) Adjustments when a multiemployer plan leaves reorganization"],[2,"If a multiemployer plan is not in reorganization in the plan year but was in reorganization in the immediately preceding plan year, any balance in the funding standard account at the close of such immediately preceding plan year—"],[3,"(i) shall be eliminated by an offsetting credit or charge (as the case may be), but"],[3,"(ii) shall be taken into account in subsequent plan years by being amortized in equal annual installments (until fully amortized) over 30 plan years."],[2,"The preceding sentence shall not apply to the extent of any accumulated funding deficiency under section 1423(a) 1 of this title as of the end of the last plan year that the plan was in reorganization."],[0,"(C) Plan payments to supplemental program or withdrawal liability payment fund"],[2,"Any amount paid by a plan during a plan year to the Pension Benefit Guaranty Corporation pursuant to section 1402 of this title or to a fund exempt under section 501(c)(22) of title 26 pursuant to section 1403 of this title shall reduce the amount of contributions considered received by the plan for the plan year."],[0,"(D) Interim withdrawal liability payments"],[2,"Any amount paid by an employer pending a final determination of the employer's withdrawal liability under part 1 of subtitle E of subchapter III and subsequently refunded to the employer by the plan shall be charged to the funding standard account in accordance with regulations prescribed by the Secretary of the Treasury."],[0,"(E) Election for deferral of charge for portion of net experience loss"],[2,"If an election is in effect under section 1082(b)(7)(F) of this title (as in effect on the day before August 17, 2006) for any plan year, the funding standard account shall be charged in the plan year to which the portion of the net experience loss deferred by such election was deferred with the amount so deferred (and paragraph (2)(B)(iii) shall not apply to the amount so charged)."],[0,"(F) Financial assistance"],[2,"Any amount of any financial assistance from the Pension Benefit Guaranty Corporation to any plan, and any repayment of such amount, shall be taken into account under this section and section 1082 of this title in such manner as is determined by the Secretary of the Treasury."],[0,"(G) Short-term benefits"],[2,"To the extent that any plan amendment increases the unfunded past service liability under the plan by reason of an increase in benefits which are not payable as a life annuity but are payable under the terms of the plan for a period that does not exceed 14 years from the effective date of the amendment, paragraph (2)(B)(ii) shall be applied separately with respect to such increase in unfunded past service liability by substituting the number of years of the period during which such benefits are payable for \"15\"."],[0,"(8) Special relief rules"],[1,"Notwithstanding any other provision of this subsection—"],[0,"(A) Amortization of net investment losses"],[0,"(i) In general"],[3,"A multiemployer plan with respect to which the solvency test under subparagraph (C) is met may treat the portion of any experience loss or gain attributable to net investment losses incurred in either or both of the first two plan years ending after August 31, 2008, as an item separate from other experience losses, to be amortized in equal annual installments (until fully amortized) over the period—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1084?type=usc&year=mostrecent&link-type=html"},"head":"§1084. Minimum funding standards for multiemployer plans","tname":"Labor","by":{"0":"8","2":"29, 5, 27, 30, 6, 23, 25, 26, 26, 26"}},{"t":"usc","label":"29 U.S.C. § 1341a","url":"https://www.law.cornell.edu/uscode/text/29/1341a","subs":["(c)(2)"],"by":{"0":"28"}},{"t":"usc","label":"29 U.S.C. § 1365","url":"https://www.law.cornell.edu/uscode/text/29/1365","subs":["(3)(A)(i)"],"by":{"0":"6-7, 33"}},{"t":"usc","label":"29 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/29/1381","subs":["(b)(1)","(a)"],"stext":{"head":"§1381. Withdrawal liability established; criteria and definitions","paras":[[0,"(a) If an employer withdraws from a multiemployer plan in a complete withdrawal or a partial withdrawal, then the employer is liable to the plan in the amount determined under this part to be the withdrawal liability."],[0,"(b) For purposes of subsection (a)—"],[1,"(1) The withdrawal liability of an employer to a plan is the amount determined under section 1391 of this title to be the allocable amount of unfunded vested benefits, adjusted—"],[2,"(A) first, by any de minimis reduction applicable under section 1389 of this title,"],[2,"(B) next, in the case of a partial withdrawal, in accordance with section 1386 of this title,"],[2,"(C) then, to the extent necessary to reflect the limitation on annual payments under section 1399(c)(1)(B) of this title, and"],[2,"(D) finally, in accordance with section 1405 of this title."],[1,"(2) The term \"complete withdrawal\" means a complete withdrawal described in section 1383 of this title."],[1,"(3) The term \"partial withdrawal\" means a partial withdrawal described in section 1385 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1381?type=usc&year=mostrecent&link-type=html"},"head":"§1381. Withdrawal liability established; criteria and definitions","tname":"Labor","by":{"0":"9, 9, 18","2":"2, 4, 4, 5"}},{"t":"usc","label":"29 U.S.C. § 1389","url":"https://www.law.cornell.edu/uscode/text/29/1389","stext":{"head":"§1389. De minimis rule","paras":[[0,"(a) Reduction of unfunded vested benefits allocable to employer withdrawn from plan"],[0,"Except in the case of a plan amended under subsection (b), the amount of the unfunded vested benefits allocable under section 1391 of this title to an employer who withdraws from a plan shall be reduced by the smaller of—"],[1,"(1) ¾ of 1 percent of the plan's unfunded vested obligations (determined as of the end of the plan year ending before the date of withdrawal), or"],[1,"(2) $50,000,"],[0,"reduced by the amount, if any, by which the unfunded vested benefits allowable to the employer, determined without regard to this subsection, exceeds $100,000."],[0,"(b) Amendment of plan for reduction of amount of unfunded vested benefits allocable to employer withdrawn from plan"],[0,"A plan may be amended to provide for the reduction of the amount determined under section 1391 of this title by not more than the greater of—"],[1,"(1) the amount determined under subsection (a), or"],[1,"(2) the lesser of—"],[2,"(A) the amount determined under subsection (a)(1), or"],[2,"(B) $100,000,"],[0,"reduced by the amount, if any, by which the amount determined under section 1391 of this title for the employer, determined without regard to this subsection, exceeds $150,000."],[0,"(c) Nonapplicability"],[0,"This section does not apply—"],[1,"(1) to an employer who withdraws in a plan year in which substantially all employers withdraw from the plan, or"],[1,"(2) in any case in which substantially all employers withdraw from the plan during a period of one or more plan years pursuant to an agreement or arrangement to withdraw, to an employer who withdraws pursuant to such agreement or arrangement."],[0,"(d) Presumption of employer withdrawal from plan pursuant to agreement or arrangement applicable in action or proceeding to determine or collect withdrawal liability"],[0,"In any action or proceeding to determine or collect withdrawal liability, if substantially all employers have withdrawn from a plan within a period of 3 plan years, an employer who has withdrawn from such plan during such period shall be presumed to have withdrawn from the plan pursuant to an agreement or arrangement, unless the employer proves otherwise by a preponderance of the evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1389?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1389. De minimis rule","tname":"Labor","by":{"0":"45","2":"19"}},{"t":"usc","label":"29 U.S.C. § 1390","url":"https://www.law.cornell.edu/uscode/text/29/1390","by":{"0":"31"}},{"t":"usc","label":"29 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/29/1391","subs":["(a)","(b)(2)(A)(ii)","(b)(2)(C)","(b)(2)(E)","(b)(2)(E)(i)","(c)(2)(C)(i)","(c)(2)(C)(i)(I)","(c)(3)(A)","(c)(3)(B)","(c)(4)(A)","(c)(4)(A)(i)","(c)","(b)(2)(A)","(b)(2)(E)(ii)"],"stext":{"head":"§1391. Methods for computing withdrawal liability","paras":[[0,"(a) Determination of amount of unfunded vested benefits allocable to employer withdrawn from plan"],[0,"The amount of the unfunded vested benefits allocable to an employer that withdraws from a plan shall be determined in accordance with subsection (b), (c), or (d) of this section."],[0,"(b) Factors determining computation of amount of unfunded vested benefits allocable to employer withdrawn from plan"],[0,"(1) Except as provided in subsections (c) and (d), the amount of unfunded vested benefits allocable to an employer that withdraws is the sum of—"],[1,"(A) the employer's proportional share of the unamortized amount of the change in the plan's unfunded vested benefits for plan years ending after September 25, 1980, as determined under paragraph (2),"],[1,"(B) the employer's proportional share, if any, of the unamortized amount of the plan's unfunded vested benefits at the end of the plan year ending before September 26, 1980, as determined under paragraph (3); and"],[1,"(C) the employer's proportional share of the unamortized amounts of the reallocated unfunded vested benefits (if any) as determined under paragraph (4)."],[0,"If the sum of the amounts determined with respect to an employer under paragraphs (2), (3), and (4) is negative, the unfunded vested benefits allocable to the employer shall be zero."],[0,"(2)(A) An employer's proportional share of the unamortized amount of the change in the plan's unfunded vested benefits for plan years ending after September 25, 1980, is the sum of the employer's proportional shares of the unamortized amount of the change in unfunded vested benefits for each plan year in which the employer has an obligation to contribute under the plan ending—"],[1,"(i) after such date, and"],[1,"(ii) before the plan year in which the withdrawal of the employer occurs."],[0,"(B) The change in a plan's unfunded vested benefits for a plan year is the amount by which—"],[1,"(i) the unfunded vested benefits at the end of the plan year; exceeds"],[1,"(ii) the sum of—"],[2,"(I) the unamortized amount of the unfunded vested benefits for the last plan year ending before September 26, 1980, and"],[2,"(II) the sum of the unamortized amounts of the change in unfunded vested benefits for each plan year ending after September 25, 1980, and preceding the plan year for which the change is determined."],[0,"(C) The unamortized amount of the change in a plan's unfunded vested benefits with respect to a plan year is the change in unfunded vested benefits for the plan year, reduced by 5 percent of such change for each succeeding plan year."],[0,"(D) The unamortized amount of the unfunded vested benefits for the last plan year ending before September 26, 1980, is the amount of the unfunded vested benefits as of the end of that plan year reduced by 5 percent of such amount for each succeeding plan year."],[0,"(E) An employer's proportional share of the unamortized amount of a change in unfunded vested benefits is the product of—"],[1,"(i) the unamortized amount of such change (as of the end of the plan year preceding the plan year in which the employer withdraws); multiplied by"],[1,"(ii) a fraction—"],[2,"(I) the numerator of which is the sum of the contributions required to be made under the plan by the employer for the year in which such change arose and for the 4 preceding plan years, and"],[2,"(II) the denominator of which is the sum for the plan year in which such change arose and the 4 preceding plan years of all contributions made by employers who had an obligation to contribute under the plan for the plan year in which such change arose reduced by the contributions made in such years by employers who had withdrawn from the plan in the year in which the change arose."],[0,"(3) An employer's proportional share of the unamortized amount of the plan's unfunded vested benefits for the last plan year ending before September 26, 1980, is the product of—"],[1,"(A) such unamortized amount; multiplied by—"],[1,"(B) a fraction—"],[2,"(i) the numerator of which is the sum of all contributions required to be made by the employer under the plan for the most recent 5 plan years ending before September 26, 1980, and"],[2,"(ii) the denominator of which is the sum of all contributions made for the most recent 5 plan years ending before September 26, 1980, by all employers—"],[3,"(I) who had an obligation to contribute under the plan for the first plan year ending on or after such date, and"],[3,"(II) who had not withdrawn from the plan before such date."],[0,"(4)(A) An employer's proportional share of the unamortized amount of the reallocated unfunded vested benefits is the sum of the employer's proportional share of the unamortized amount of the reallocated unfunded vested benefits for each plan year ending before the plan year in which the employer withdrew from the plan."],[0,"(B) Except as otherwise provided in regulations prescribed by the corporation, the reallocated unfunded vested benefits for a plan year is the sum of—"],[1,"(i) any amount which the plan sponsor determines in that plan year to be uncollectible for reasons arising out of cases or proceedings under title 11, or similar proceedings.1"],[1,"(ii) any amount which the plan sponsor determines in that plan year will not be assessed as a result of the operation of section 1389, 1399(c)(1)(B), or 1405 of this title against an employer to whom a notice described in section 1399 of this title has been sent, and"],[1,"(iii) any amount which the plan sponsor determines to be uncollectible or unassessable in that plan year for other reasons under standards not inconsistent with regulations prescribed by the corporation."],[0,"(C) The unamortized amount of the reallocated unfunded vested benefits with respect to a plan year is the reallocated unfunded vested benefits for the plan year, reduced by 5 percent of such reallocated unfunded vested benefits for each succeeding plan year."],[0,"(D) An employer's proportional share of the unamortized amount of the reallocated unfunded vested benefits with respect to a plan year is the product of—"],[1,"(i) the unamortized amount of the reallocated unfunded vested benefits (as of the end of the plan year preceding the plan year in which the employer withdraws); multiplied by"],[1,"(ii) the fraction defined in paragraph (2)(E)(ii)."],[0,"(c) Amendment of multiemployer plan for determination respecting amount of unfunded vested benefits allocable to employer withdrawn from plan; factors determining computation of amount"],[0,"(1) A multiemployer plan, other than a plan which primarily covers employees in the building and construction industry, may be amended to provide that the amount of unfunded vested benefits allocable to an employer that withdraws from the plan is an amount determined under paragraph (2), (3), (4), or (5) of this subsection, rather than under subsection (b) or (d). A plan described in section 1383(b)(1)(B)(i) of this title (relating to the building and construction industry) may be amended, to the extent provided in regulations prescribed by the corporation, to provide that the amount of the unfunded vested benefits allocable to an employer not described in section 1383(b)(1)(A) of this title shall be determined in a manner different from that provided in subsection (b)."],[0,"(2)(A) The amount of the unfunded vested benefits allocable to any employer under this paragraph is the sum of the amounts determined under subparagraphs (B) and (C)."],[0,"(B) The amount determined under this subparagraph is the product of—"],[1,"(i) the plan's unfunded vested benefits as of the end of the last plan year ending before September 26, 1980, reduced as if those obligations were being fully amortized in level annual installments over 15 years beginning with the first plan year ending on or after such date; multiplied by"],[1,"(ii) a fraction—"],[2,"(I) the numerator of which is the sum of all contributions required to be made by the employer under the plan for the last 5 plan years ending before September 26, 1980, and"],[2,"(II) the denominator of which is the sum of all contributions made for the last 5 plan years ending before September 26, 1980, by all employers who had an obligation to contribute under the plan for the first plan year ending after September 25, 1980, and who had not withdrawn from the plan before such date."],[0,"(C) The amount determined under this subparagraph is the product of—"],[1,"(i) an amount equal to—"],[2,"(I) the plan's unfunded vested benefits as of the end of the plan year preceding the plan year in which the employer withdraws, less"],[2,"(II) the sum of the value as of such date of all outstanding claims for withdrawal liability which can reasonably be expected to be collected, with respect to employers withdrawing before such plan year, and that portion of the amount determined under subparagraph (B)(i) which is allocable to employers who have an obligation to contribute under the plan in the plan year preceding the plan year in which the employer withdraws and who also had an obligation to contribute under the plan for the first plan year ending after September 25, 1980; multiplied by"],[1,"(ii) a fraction—"],[2,"(I) the numerator of which is the total amount required to be contributed under the plan by the employer for the last 5 plan years ending before the date on which the employer withdraws, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1391?type=usc&year=mostrecent&link-type=html"},"op":11,"ar":3,"head":"§1391. Methods for computing withdrawal liability","tname":"Labor","by":{"0":"18, 18, 19, 19, 20, 1, 9, 14, 18, 1, 9, 14, 18, 20, 1, 9, 14, 18-19, 19, 1, 9, 14, 18, 20","2":"2, 5, 9-11, 13-15, 18-21, 23, 24, 26-28, 31, 32, 5, 11, 14, 19","3":"1, 3, 5-8, 11, 16-20, 22, 24, 4, 3-4, 4, 3, 3, 3"}},{"t":"usc","label":"29 U.S.C. § 1393","url":"https://www.law.cornell.edu/uscode/text/29/1393","subs":["(a)","(a)(1)","(a)(1)(1982)","(b)","(b)(1)","(c)","(c)(A)","(a)(2)","(b)(2)"],"stext":{"head":"§1393. Actuarial assumptions","paras":[[0,"(a) Use by plan actuary in determining unfunded vested benefits of a plan for computing withdrawal liability of employer"],[0,"The corporation may prescribe by regulation actuarial assumptions which may be used by a plan actuary in determining the unfunded vested benefits of a plan for purposes of determining an employer's withdrawal liability under this part. Withdrawal liability under this part shall be determined by each plan on the basis of—"],[1,"(1) actuarial assumptions and methods which, in the aggregate, are reasonable (taking into account the experience of the plan and reasonable expectations) and which, in combination, offer the actuary's best estimate of anticipated experience under the plan, or"],[1,"(2) actuarial assumptions and methods set forth in the corporation's regulations for purposes of determining an employer's withdrawal liability."],[0,"(b) Factors determinative of unfunded vested benefits of plan for computing withdrawal liability of employer"],[0,"In determining the unfunded vested benefits of a plan for purposes of determining an employer's withdrawal liability under this part, the plan actuary may—"],[1,"(1) rely on the most recent complete actuarial valuation used for purposes of section 412 of title 26 and reasonable estimates for the interim years of the unfunded vested benefits, and"],[1,"(2) in the absence of complete data, rely on the data available or on data secured by a sampling which can reasonably be expected to be representative of the status of the entire plan."],[0,"(c) Determination of amount of unfunded vested benefits"],[0,"For purposes of this part, the term \"unfunded vested benefits\" means with respect to a plan, an amount equal to—"],[1,"(A) the value of nonforfeitable benefits under the plan, less"],[1,"(B) the value of the assets of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1393?type=usc&year=mostrecent&link-type=html"},"op":7,"ar":3,"head":"§1393. Actuarial assumptions","tname":"Labor","by":{"0":"16, 29, 34, 37-38, 41-43, 43, 16, 34, 39, 41-42, 26, 43, 43, 1, 14, 23-24, 26, 39","2":"10, 21-23, 4, 22, 28, 30, 5, 23, 24, 23, 23, 4","3":"3, 5, 8-9, 12, 16-17, 19-20, 2, 7-8, 10-11, 11, 6-7"}},{"t":"usc","label":"29 U.S.C. § 1394","url":"https://www.law.cornell.edu/uscode/text/29/1394","subs":["(a)"],"stext":{"head":"§1394. Application of plan amendments; exception","paras":[[0,"(a) No plan rule or amendment adopted after January 31, 1981, under section 1389 or 1391(c) of this title may be applied without the employer's consent with respect to liability for a withdrawal or partial withdrawal which occurred before the date on which the rule or amendment was adopted."],[0,"(b) All plan rules and amendments authorized under this part shall operate and be applied uniformly with respect to each employer, except that special provisions may be made to take into account the creditworthiness of an employer. The plan sponsor shall give notice to all employers who have an obligation to contribute under the plan and to all employee organizations representing employees covered under the plan of any plan rules or amendments adopted pursuant to this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1394?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":2,"head":"§1394. Application of plan amendments; exception","tname":"Labor","by":{"0":"45, 15, 30, 32","2":"8, 10, 19-21, 31, 19, 21","3":"17-19"}},{"t":"usc","label":"29 U.S.C. § 1399","url":"https://www.law.cornell.edu/uscode/text/29/1399","subs":["(c)(1)(B)"],"stext":{"head":"§1399. Notice, collection, etc., of withdrawal liability","paras":[[0,"(a) Furnishing of information by employer to plan sponsor"],[0,"An employer shall, within 30 days after a written request from the plan sponsor, furnish such information as the plan sponsor reasonably determines to be necessary to enable the plan sponsor to comply with the requirements of this part."],[0,"(b) Notification, demand for payment, and review upon complete or partial withdrawal by employer"],[0,"(1) As soon as practicable after an employer's complete or partial withdrawal, the plan sponsor shall—"],[1,"(A) notify the employer of—"],[2,"(i) the amount of the liability, and"],[2,"(ii) the schedule for liability payments, and"],[1,"(B) demand payment in accordance with the schedule."],[0,"(2)(A) No later than 90 days after the employer receives the notice described in paragraph (1), the employer—"],[1,"(i) may ask the plan sponsor to review any specific matter relating to the determination of the employer's liability and the schedule of payments,"],[1,"(ii) may identify any inaccuracy in the determination of the amount of the unfunded vested benefits allocable to the employer, and"],[1,"(iii) may furnish any additional relevant information to the plan sponsor."],[0,"(B) After a reasonable review of any matter raised, the plan sponsor shall notify the employer of—"],[1,"(i) the plan sponsor's decision,"],[1,"(ii) the basis for the decision, and"],[1,"(iii) the reason for any change in the determination of the employer's liability or schedule of liability payments."],[0,"(c) Payment requirements; amount, etc."],[0,"(1)(A)(i) Except as provided in subparagraphs (B) and (D) of this paragraph and in paragraphs (4) and (5), an employer shall pay the amount determined under section 1391 of this title, adjusted if appropriate first under section 1389 of this title and then under section 1386 of this title over the period of years necessary to amortize the amount in level annual payments determined under subparagraph (C), calculated as if the first payment were made on the first day of the plan year following the plan year in which the withdrawal occurs and as if each subsequent payment were made on the first day of each subsequent plan year. Actual payment shall commence in accordance with paragraph (2)."],[0,"(ii) The determination of the amortization period described in clause (i) shall be based on the assumptions used for the most recent actuarial valuation for the plan."],[0,"(B) In any case in which the amortization period described in subparagraph (A) exceeds 20 years, the employer's liability shall be limited to the first 20 annual payments determined under subparagraph (C)."],[0,"(C)(i) Except as provided in subparagraph (E), the amount of each annual payment shall be the product of—"],[1,"(I) the average annual number of contribution base units for the period of 3 consecutive plan years, during the period of 10 consecutive plan years ending before the plan year in which the withdrawal occurs, in which the number of contribution base units for which the employer had an obligation to contribute under the plan is the highest, and"],[1,"(II) the highest contribution rate at which the employer had an obligation to contribute under the plan during the 10 plan years ending with the plan year in which the withdrawal occurs."],[0,"For purposes of the preceding sentence, a partial withdrawal described in section 1385(a)(1) of this title shall be deemed to occur on the last day of the first year of the 3-year testing period described in section 1385(b)(1)(B)(i) of this title."],[0,"(ii)(I) A plan may be amended to provide that for any plan year ending before 1986 the amount of each annual payment shall be (in lieu of the amount determined under clause (i)) the average of the required employer contributions under the plan for the period of 3 consecutive plan years (during the period of 10 consecutive plan years ending with the plan year preceding the plan year in which the withdrawal occurs) for which such required contributions were the highest."],[0,"(II) Subparagraph (B) shall not apply to any plan year to which this clause applies."],[0,"(III) This clause shall not apply in the case of any withdrawal described in subparagraph (D)."],[0,"(IV) If under a plan this clause applies to any plan year but does not apply to the next plan year, this clause shall not apply to any plan year after such next plan year."],[0,"(V) For purposes of this clause, the term \"required contributions\" means, for any period, the amounts which the employer was obligated to contribute for such period (not taking into account any delinquent contribution for any other period)."],[0,"(iii) A plan may be amended to provide that for the first plan year ending on or after September 26, 1980, the number \"5\" shall be substituted for the number \"10\" each place it appears in clause (i) or clause (ii) (whichever is appropriate). If the plan is so amended, the number \"5\" shall be increased by one for each succeeding plan year until the number \"10\" is reached."],[0,"(D) In any case in which a multiemployer plan terminates by the withdrawal of every employer from the plan, or in which substantially all the employers withdraw from a plan pursuant to an agreement or arrangement to withdraw from the plan—"],[1,"(i) the liability of each such employer who has withdrawn shall be determined (or redetermined) under this paragraph without regard to subparagraph (B), and"],[1,"(ii) notwithstanding any other provision of this part, the total unfunded vested benefits of the plan shall be fully allocated among all such employers in a manner not inconsistent with regulations which shall be prescribed by the corporation."],[0,"Withdrawal by an employer from a plan, during a period of 3 consecutive plan years within which substantially all the employers who have an obligation to contribute under the plan withdraw, shall be presumed to be a withdrawal pursuant to an agreement or arrangement, unless the employer proves otherwise by a preponderance of the evidence."],[0,"(E) In the case of a partial withdrawal described in section 1385(a) of this title, the amount of each annual payment shall be the product of—"],[1,"(i) the amount determined under subparagraph (C) (determined without regard to this subparagraph), multiplied by"],[1,"(ii) the fraction determined under section 1386(a)(2) of this title."],[0,"(2) Withdrawal liability shall be payable in accordance with the schedule set forth by the plan sponsor under subsection (b)(1) beginning no later than 60 days after the date of the demand notwithstanding any request for review or appeal of determinations of the amount of such liability or of the schedule."],[0,"(3) Each annual payment determined under paragraph (1)(C) shall be payable in 4 equal installments due quarterly, or at other intervals specified by plan rules. If a payment is not made when due, interest on the payment shall accrue from the due date until the date on which the payment is made."],[0,"(4) The employer shall be entitled to prepay the outstanding amount of the unpaid annual withdrawal liability payments determined under paragraph (1)(C), plus accrued interest, if any, in whole or in part, without penalty. If the prepayment is made pursuant to a withdrawal which is later determined to be part of a withdrawal described in paragraph (1)(D), the withdrawal liability of the employer shall not be limited to the amount of the prepayment."],[0,"(5) In the event of a default, a plan sponsor may require immediate payment of the outstanding amount of an employer's withdrawal liability, plus accrued interest on the total outstanding liability from the due date of the first payment which was not timely made. For purposes of this section, the term \"default\" means—"],[1,"(A) the failure of an employer to make, when due, any payment under this section, if the failure is not cured within 60 days after the employer receives written notification from the plan sponsor of such failure, and"],[1,"(B) any other event defined in rules adopted by the plan which indicates a substantial likelihood that an employer will be unable to pay its withdrawal liability."],[0,"(6) Except as provided in paragraph (1)(A)(ii), interest under this subsection shall be charged at rates based on prevailing market rates for comparable obligations, in accordance with regulations prescribed by the corporation."],[0,"(7) A multiemployer plan may adopt rules for other terms and conditions for the satisfaction of an employer's withdrawal liability if such rules—"],[1,"(A) are consistent with this chapter, and"],[1,"(B) are not inconsistent with regulations of the corporation."],[0,"(8) In the case of a terminated multiemployer plan, an employer's obligation to make payments under this section ceases at the end of the plan year in which the assets of the plan (exclusive of withdrawal liability claims) are sufficient to meet all obligations of the plan, as determined by the corporation."],[0,"(d) Applicability of statutory prohibitions"],[0,"The prohibitions provided in section 1106(a) of this title do not apply to any action required or permitted under this part or to any arrangement relating to withdrawal liability involving the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1399?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1399. Notice, collection, etc., of withdrawal liability","tname":"Labor","by":{"0":"45"}},{"t":"usc","label":"29 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/29/1401","subs":["(a)","(b)","(a)(3)(B)","(b)(2)"],"stext":{"head":"§1401. Resolution of disputes","paras":[[0,"(a) Arbitration proceedings; matters subject to arbitration, procedures applicable, etc."],[0,"(1) Any dispute between an employer and the plan sponsor of a multiemployer plan concerning a determination made under sections 1381 through 1399 of this title shall be resolved through arbitration. Either party may initiate the arbitration proceeding within a 60-day period after the earlier of—"],[1,"(A) the date of notification to the employer under section 1399(b)(2)(B) of this title, or"],[1,"(B) 120 days after the date of the employer's request under section 1399(b)(2)(A) of this title."],[0,"The parties may jointly initiate arbitration within the 180-day period after the date of the plan sponsor's demand under section 1399(b)(1) of this title."],[0,"(2) An arbitration proceeding under this section shall be conducted in accordance with fair and equitable procedures to be promulgated by the corporation. The plan sponsor may purchase insurance to cover potential liability of the arbitrator. If the parties have not provided for the costs of the arbitration, including arbitrator's fees, by agreement, the arbitrator shall assess such fees. The arbitrator may also award reasonable attorney's fees."],[0,"(3)(A) For purposes of any proceeding under this section, any determination made by a plan sponsor under sections 1381 through 1399 of this title and section 1405 of this title is presumed correct unless the party contesting the determination shows by a preponderance of the evidence that the determination was unreasonable or clearly erroneous."],[0,"(B) In the case of the determination of a plan's unfunded vested benefits for a plan year, the determination is presumed correct unless a party contesting the determination shows by a preponderance of evidence that—"],[1,"(i) the actuarial assumptions and methods used in the determination were, in the aggregate, unreasonable (taking into account the experience of the plan and reasonable expectations), or"],[1,"(ii) the plan's actuary made a significant error in applying the actuarial assumptions or methods."],[0,"(b) Alternative collection proceedings; civil action subsequent to arbitration award; conduct of arbitration proceedings"],[0,"(1) If no arbitration proceeding has been initiated pursuant to subsection (a), the amounts demanded by the plan sponsor under section 1399(b)(1) of this title shall be due and owing on the schedule set forth by the plan sponsor. The plan sponsor may bring an action in a State or Federal court of competent jurisdiction for collection."],[0,"(2) Upon completion of the arbitration proceedings in favor of one of the parties, any party thereto may bring an action, no later than 30 days after the issuance of an arbitrator's award, in an appropriate United States district court in accordance with section 1451 of this title to enforce, vacate, or modify the arbitrator's award."],[0,"(3) Any arbitration proceedings under this section shall, to the extent consistent with this subchapter, be conducted in the same manner, subject to the same limitations, carried out with the same powers (including subpena power), and enforced in United States courts as an arbitration proceeding carried out under title 9."],[0,"(c) Presumption respecting finding of fact by arbitrator"],[0,"In any proceeding under subsection (b), there shall be a presumption, rebuttable only by a clear preponderance of the evidence, that the findings of fact made by the arbitrator were correct."],[0,"(d) Payments by employer prior and subsequent to determination by arbitrator; adjustments; failure of employer to make payments"],[0,"Payments shall be made by an employer in accordance with the determinations made under this part until the arbitrator issues a final decision with respect to the determination submitted for arbitration, with any necessary adjustments in subsequent payments for overpayments or underpayments arising out of the decision of the arbitrator with respect to the determination. If the employer fails to make timely payment in accordance with such final decision, the employer shall be treated as being delinquent in the making of a contribution required under the plan (within the meaning of section 1145 of this title)."],[0,"(e) Procedures applicable to certain disputes"],[0,"(1) In general"],[1,"If—"],[2,"(A) a plan sponsor of a plan determines that—"],[3,"(i) a complete or partial withdrawal of an employer has occurred, or"],[3,"(ii) an employer is liable for withdrawal liability payments with respect to the complete or partial withdrawal of an employer from the plan,"],[2,"(B) such determination is based in whole or in part on a finding by the plan sponsor under section 1392(c) of this title that a principal purpose of a transaction that occurred before January 1, 1999, was to evade or avoid withdrawal liability under this subtitle, and"],[2,"(C) such transaction occurred at least 5 years before the date of the complete or partial withdrawal,"],[1,"then the special rules under paragraph (2) shall be used in applying subsections (a) and (d) of this section and section 1399(c) of this title to the employer."],[0,"(2) Special rules"],[0,"(A) Determination"],[2,"Notwithstanding subsection (a)(3)—"],[3,"(i) a determination by the plan sponsor under paragraph (1)(B) shall not be presumed to be correct, and"],[3,"(ii) the plan sponsor shall have the burden to establish, by a preponderance of the evidence, the elements of the claim under section 1392(c) of this title that a principal purpose of the transaction was to evade or avoid withdrawal liability under this subtitle."],[2,"Nothing in this subparagraph shall affect the burden of establishing any other element of a claim for withdrawal liability under this subtitle."],[0,"(B) Procedure"],[2,"Notwithstanding subsection (d) and section 1399(c) of this title, if an employer contests the plan sponsor's determination under paragraph (1) through an arbitration proceeding pursuant to subsection (a), or through a claim brought in a court of competent jurisdiction, the employer shall not be obligated to make any withdrawal liability payments until a final decision in the arbitration proceeding, or in court, upholds the plan sponsor's determination."],[0,"(f) Procedures applicable to certain disputes"],[0,"(1) In general.—If—"],[1,"(A) a plan sponsor of a plan determines that—"],[2,"(i) a complete or partial withdrawal of an employer has occurred, or"],[2,"(ii) an employer is liable for withdrawal liability payments with respect to such complete or partial withdrawal, and"],[1,"(B) such determination is based in whole or in part on a finding by the plan sponsor under section 1392(c) of this title that a principal purpose of any transaction which occurred after December 31, 1998, and at least 5 years (2 years in the case of a small employer) before the date of the complete or partial withdrawal was to evade or avoid withdrawal liability under this subtitle,"],[0,"then the person against which the withdrawal liability is assessed based solely on the application of section 1392(c) of this title may elect to use the special rule under paragraph (2) in applying subsection (d) of this section and section 1399(c) of this title to such person."],[0,"(2) Special rule.—Notwithstanding subsection (d) and section 1399(c) of this title, if an electing person contests the plan sponsor's determination with respect to withdrawal liability payments under paragraph (1) through an arbitration proceeding pursuant to subsection (a), through an action brought in a court of competent jurisdiction for review of such an arbitration decision, or as otherwise permitted by law, the electing person shall not be obligated to make the withdrawal liability payments until a final decision in the arbitration proceeding, or in court, upholds the plan sponsor's determination, but only if the electing person—"],[1,"(A) provides notice to the plan sponsor of its election to apply the special rule in this paragraph within 90 days after the plan sponsor notifies the electing person of its liability by reason of the application of section 1392(c) of this title; and"],[1,"(B) if a final decision in the arbitration proceeding, or in court, of the withdrawal liability dispute has not been rendered within 12 months from the date of such notice, the electing person provides to the plan, effective as of the first day following the 12-month period, a bond issued by a corporate surety company that is an acceptable surety for purposes of section 1112 of this title, or an amount held in escrow by a bank or similar financial institution satisfactory to the plan, in an amount equal to the sum of the withdrawal liability payments that would otherwise be due under subsection (d) and section 1399(c) of this title for the 12-month period beginning with the first anniversary of such notice. Such bond or escrow shall remain in effect until there is a final decision in the arbitration proceeding, or in court, of the withdrawal liability dispute, at which time such bond or escrow shall be paid to the plan if such final decision upholds the plan sponsor's determination."],[0,"(3) Definition of small employer.—For purposes of this subsection—"],[1,"(A) In general.—The term \"small employer\" means any employer which, for the calendar year in which the transaction referred to in paragraph (1)(B) occurred and for each of the 3 preceding years, on average—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1401?type=usc&year=mostrecent&link-type=html"},"head":"§1401. Resolution of disputes","tname":"Labor","by":{"0":"12, 13","2":"6, 28, 30, 6"}},{"t":"usc","label":"29 U.S.C. § 1405","url":"https://www.law.cornell.edu/uscode/text/29/1405","by":{"0":"45"}},{"t":"law","label":"Pub. L. No. 96-364","url":"https://www.govinfo.gov/link/statute/94/1208","by":{"0":"7, 9","2":"4"}},{"t":"law","label":"Pub. L. No. 101-239","url":"https://www.govinfo.gov/link/statute/103/2106","by":{"0":"8"}},{"t":"reg","label":"29 C.F.R. § 4065.3","url":"https://www.ecfr.gov/current/title-29/section-4065.3","subs":["(b)"],"by":{"0":"7, 33"}},{"t":"reg","label":"Methods for Computing Withdrawal Liability; Reallocation Liability Upon Mass Withdrawal; Pension Protection Act of 2006, 73 Fed. Reg. 79,628","url":"https://www.govinfo.gov/link/fr/73/79628","by":{"0":"19"}},{"t":"reg","label":"Revision of Schedule B (Actuarial Information) and Permanent Waiver of Certain Actuarial Information in the Annual Report, 44 Fed. Reg. 5440","url":"https://www.govinfo.gov/link/fr/44/5440","by":{"0":"33"}},{"t":"case","label":"Becerra v. Empire Health Found.","cite":"597 U.S. 424","y":2022,"id":"2021/20-1312","sc":1,"op":1,"sum":"For purposes of calculating the Medicare fraction—one of two fractions the Medicare program uses to adjust the rates paid to hospitals that serve a higher-than-usual percentage of low-income patients—those individuals “entitled to [Medicare Part A] benefits” are all those qualifying for the program, regardless of whether they receive Medicare payments for part or all of a hospital stay.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Balt.","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"30"}},{"t":"case","label":"Combs v. Classic Coal Corp.","cite":"1990 WL 66583","y":1990,"court":"D.D.C. Apr. 6","by":{"1":"24"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil Grp., Inc.","cite":"590 U.S. 212","y":2020,"id":"2019/18-1233","sc":1,"op":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"1":"18","2":"15"}},{"t":"case","label":"Sandoz Inc. v. Amgen Inc.","cite":"582 U.S. 1","y":2017,"id":"2016/15-1039","sc":1,"sum":"The Court determined that the Biologics Price Competition and Innovation Act of 2009 allows for commercial notice of a “biosimilar product” to be effective if given prior to approval by the Food and Drug Administration (FDA), but that the Act’s notice requirement is not enforceable with an injunction.","sumSrc":"Oyez","by":{"1":"16, 30, 31","2":"20","3":"18"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Transpro, Inc. v. Leggett & Platt, Inc.","cite":"297 F. App’x 434","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/297/434/","by":{"1":"26"}},{"t":"case","label":"Trs. of Loc. 138 Pension Tr. Fund v. F.W. Honerkamp Co.","cite":"692 F.3d 127","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/692/127/","by":{"1":"5"}},{"t":"case","label":"United States v. Munro-Van Helms Co.","cite":"243 F.2d 10","y":1957,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/243/10/","by":{"1":"23","2":"12"}},{"t":"case","label":"Utah Dep’t of Transp. v. Boggess-Draper Co.","cite":"467 P.3d 840","y":2020,"court":"Utah","url":"https://www.courtlistener.com/c/P.3d/467/840/","by":{"1":"26","3":"13"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"sum":"Respondents, the defendants in a District Court suit instituted by petitioner law firm on behalf of a client, filed a motion to dismiss the complaint as having no basis in fact and a motion for sanctions under Federal Rule of Civil Procedure 11 on the ground that the firm had not made sufficient prefiling inquiries to support the complaint's allegations. Rule 11-after specifying, interalia, that an attorney's …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"E.I. DuPont de Nemours & Co. v. Davis","cite":"264 U.S. 456","y":1924,"id":"scdb/1923-110","sc":1,"sum":"1. In a complaint showing by apt allegation that the plaintiff sues as the Director General of Railroads continued in that office by the President under §§ 202 and 211 of the Transportation Act, a description of him \"as agent \", appointed under § 206 of the act, may be rejected as surplusage.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Eastman Kodak Co. v. Image Tech. Servs., Inc.","cite":"504 U.S. 451","y":1992,"id":"1991/90-1029","sc":1,"sum":"After respondent independent service organizations (ISO's) began servicing copying and micrographic equipment manufactured by petitioner Eastman Kodak Co., Kodak adopted policies to limit the availability to ISO's of replacement parts for its equipment and to make it more difficult for ISO's to compete with it in servicing such equipment. Respondents then filed this action, alleging, inter alia,that Kodak had …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Esteras v. United States","cite":"145 S. Ct. 2031","y":2025,"id":"2024/23-7483","sc":1,"sum":"A district court considering whether to revoke a defendant’s term of supervised release may not consider 18 U. S. C. §3553(a)(2)(A), which covers retribution vis-à-vis the defendant’s underlying criminal offense.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"33"}},{"t":"case","label":"Gallardo v. Marstiller","cite":"596 U.S. 420","y":2022,"id":"2021/20-1263","sc":1,"sum":"The Medicaid Act permits a State to seek reimbursement from settlement payments allocated for future medical care.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20","3":"18"}},{"t":"case","label":"Latimore v. Citibank Fed. Sav. Bank","cite":"151 F.3d 712","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/712/","by":{"2":"16"}},{"t":"case","label":"Liteky v. United States","cite":"510 U.S. 540","y":1994,"id":"1993/92-6921","sc":1,"sum":"Before and during petitioners' 1991 trial on federal criminal charges, the District Judge denied defense motions that he recuse himself pursuant to 28 U. S. C. §455(a), which requires a federal judge to \"disqualify himself in any proceeding in which his impartiality might reasonably be questioned.\" The first motion was based on rulings and statements this same judge made, which allegedly displayed impatience, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Massaro v. Palladino","cite":"19 F.4th 197","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/19/197/","by":{"2":"5"}},{"t":"case","label":"Okerlund v. United States","cite":"365 F.3d 1044","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/365/1044/","by":{"2":"17"}},{"t":"case","label":"Pension Benefit Guar. Corp. v. Yahn & McDonnell, Inc.","cite":"481 U.S. 735","y":1987,"id":"1986/86-231","sc":1,"by":{"2":"29"}},{"t":"case","label":"Richardson v. Perales","cite":"402 U.S. 389","y":1971,"id":"1970/108","sc":1,"sum":"Written reports by physicians who have examined claimant for disability insurance benefits under Social Security Act constitute \"substantial evidence\" supporting a nondisability finding within the standard of § 205 (g) of the Act, notwithstanding the reports' hearsay character, the absence of cross-examination (through claimant's failure to exercise his subpoena rights), and the directly opposing testimony by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Rosner v. Metropolitan Prop. & Liab. Ins. Co.","cite":"236 F.3d 96","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/236/96/","by":{"2":"14"}},{"t":"case","label":"Sinclair Refin. Co. v. Jenkins Petroleum Process Co.","cite":"289 U.S. 689","y":1933,"id":"scdb/1932-096","sc":1,"sum":"1. A bill of discovery will lie in a federal court to aid in proving damages of the plaintiff in an action on the law side, if the complication of accounts or other practical impediments make it necessary that the evidence be sifted in advance of the jury trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Stephens v. U.S. Airways Grp., Inc.","cite":"644 F.3d 437","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/644/437/","by":{"2":"16"}},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Gypsum Co.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"sum":"An insurer with financial responsibility for bankruptcy claims is a “party in interest” under 11 U. S. C. §1109(b) that “may raise and may appear and be heard on any issue” in a Chapter 11 case.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"28"}},{"t":"case","label":"United Retail & Wholesale Emps. Teamsters Union Local No. 115 Pension Plan v. Yahn & McDonnell, Inc.","cite":"787 F.2d 128","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/787/128/","by":{"2":"29"}},{"t":"case","label":"United States v. Miller","cite":"317 U.S. 369","y":1943,"id":"scdb/1942-034","sc":1,"sum":"1. Where, from the date of its authorization by Act of Congress, a federal reclamation project included the relocation of a line of railroad, and a probable route was marked out over certain lands subsequently taken in eminent domain proceedings, it is proper,. in determining just compensation, to exclude from value as of the date of the taking such increase as occurred since the date of the authorization of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"16"}},{"t":"usc","label":"29 U.S.C. § 1054","url":"https://www.law.cornell.edu/uscode/text/29/1054","subs":["(c)(3)"],"by":{"2":"16"}},{"t":"usc","label":"29 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/29/1301","subs":["(a)(10)"],"by":{"2":"5"}},{"t":"usc","label":"29 U.S.C. § 1382","url":"https://www.law.cornell.edu/uscode/text/29/1382","by":{"2":"5"}},{"t":"usc","label":"29 U.S.C. § 1432","url":"https://www.law.cornell.edu/uscode/text/29/1432","subs":["(c)(1)","(c)(2)"],"by":{"2":"20, 20"}},{"t":"reg","label":"87 Fed. Reg. 62,316","url":"https://www.govinfo.gov/link/fr/87/62316","by":{"2":"4, 5"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"587 U.S. 566","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"10"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"586 U.S. 105","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"23"}}]};